// ===== Editable content =====
const CFG={passcode:'1313',name:'Jahanvi',
 t1:"Jahanvi ❤️‍🩹, main apne rishte ki shuruaat sach se karna chahta tha. Isliye maine tujhe bataya tha ki meri pehle ek girlfriend thi, lekin mera koi serious relationship nahi tha. Maine ye baat isliye share ki thi taaki tu bhi apne past ke baare mein mujhse khulkar baat kar sake. 🥺 Mujhe tujhse pehli nazar mein hi pyaar ho gaya tha. ❤️",
 t2:"Mujhe pata tha ki woh teri fake ID thi, aur shayad tu uske through mere character ko samajhne ki koshish kar rahi thi. Mujhe laga tha ki tu meri loyalty check kar rahi hai, isliye maine us waqt baat ko seriously nahi liya. Lekin shayad mujhe situation ko aur samajhdari se handle karna chahiye tha. 💔 Maine sabka dil jeet liya, par shayad tera bharosa nahi jeet paaya. Aur iska mujhe sach mein afsos hai. 🥺",
 t3:"Jahanvi, main tujhe khone se bahut darta hoon. 😔 Mere birthday wale din maine apne mann ki bhadaas tujh par nikaal di. Mujhe aisa nahi karna chahiye tha. I'm really sorry. 🙏❤️‍🩹 Tu chahe toh mujhe maaf karne mein apna waqt le sakti hai. Main apni galti ko samajhna aur apne behaviour mein sudhaar karna chahta hoon. Main tujhe hurt karna nahi chahta tha. 🥀",
 letter:"<b>My Dearest Jahanvi ❤️,</b>Jahanvi, is Diwali har taraf roshni hai, bas meri Diwali tere bina sooni hai. 🪔❤️ I really miss your voice, your smile and those little moments. Kaash is Diwali ek baar teri awaaz sun paata. 🥺 Main tujhe bahut miss karta hoon. Agar kabhi tera mann ho, toh baat kar lena. Teri khushi aur sukoon hamesha mere liye important rahenge.Happy Diwali meri dil-wali💗",
 treaty:"Thank you for being the most forgiving and wonderful person. I love you to the moon and back and I'm never letting go! 💚🙏",
 steps:[10,20,40,60,90,100],imgs:{sleep:'data:image/png;base64,',hug:'data:image/png;base64,'}};
const I18N={en:{pass:'ENTER PASSCODE',wait:'Something special is waiting for you',ready:"But I'm ready to make it right.",listen:'Listen to my heart 💝'},
 hi:{pass:'पासकोड डालो',wait:'कुछ खास तुम्हारा इंतज़ार कर रहा है',ready:'पर मैं इसे सुधारने को तैयार हूँ।',listen:'मेरे दिल की सुनो 💝'}};
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
let shown=0,cur=0,entry='',pi=0,done={},timer;
// ----- navigation -----
function go(n){if(n===10)reset();if(n===8&&pi<CFG.steps.length)return;clearInterval(timer);cur=n;$$('.scr').forEach((e,i)=>e.classList.toggle('on',i===n));
 const el=$('#s'+n).querySelector('.tw');if(el)typeIn(el);if(n===8)burst();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)go(+b.dataset.go)});
// ----- typewriter (card grows as text appears; tap card to skip) -----
function typeIn(el){const html=CFG[el.dataset.k],isL=el.dataset.k==='letter';
 if(done[el.id]){el.innerHTML=html;if(isL){$('#mas').style.display='';$('#lb').style.visibility='visible'}return}
 const tmp=document.createElement('div');tmp.innerHTML=html;const txt=tmp.innerHTML;let i=0;el.innerHTML='';
 if(isL){$('#mas').style.display='none';$('#lb').style.visibility='hidden'}
 const fin=()=>{clearInterval(timer);el.innerHTML=html;done[el.id]=1;if(isL){$('#mas').style.display='';$('#lb').style.visibility='visible'}};
 el.onclick=fin;timer=setInterval(()=>{i+=2;let s=txt.slice(0,i);const o=s.lastIndexOf('<'),c=s.lastIndexOf('>');if(o>c)s=s.slice(0,o);el.innerHTML=s;el.scrollTop=1e5;if(i>=txt.length)fin()},28);}
// ----- floating hearts -----
for(let i=0;i<16;i++){const h=document.createElement('i');h.textContent='♥';h.style.cssText=`left:${Math.random()*96}%;top:${50+Math.random()*70}%;font-size:${9+Math.random()*13}px;animation-delay:${-Math.random()*11}s;animation-duration:${9+Math.random()*9}s`;$('#bg').append(h)}
// ----- passcode -----
[1,2,3,4,5,6,7,8,9,'',0,'⌫'].forEach(k=>{const b=document.createElement('button');b.textContent=k;if(k==='')b.style.visibility='hidden';if(k==='⌫')b.className='x';b.onclick=()=>key(k);$('#pad').append(b)});
function key(k){if(k==='⌫')entry=entry.slice(0,-1);else if(entry.length<4)entry+=k;
 [...$('#dots').children].forEach((d,i)=>{d.className=i<entry.length?'f':'';d.textContent=entry[i]||''});
 if(entry.length===4){if(entry===CFG.passcode)setTimeout(()=>go(1),350);else{$('#dots').classList.add('shake');setTimeout(()=>{$('#dots').classList.remove('shake');entry='';key('⌫')},500)}}}
document.addEventListener('keydown',e=>{if(cur===0){if(/^\d$/.test(e.key))key(e.key);if(e.key==='Backspace')key('⌫')}});
// ----- content -----
$('#wel').innerHTML='I Messed Up, '+CFG.name+'<br>❤️😢';$('#tp').textContent=CFG.treaty;$('#qn').textContent=CFG.name+' ❤️';
// ----- envelope -----
$('#env').onclick=()=>{$('#env').classList.add('open');setTimeout(()=>{go(6);$('#env').classList.remove('open')},650)};
// ----- forgiveness: only user taps move it -----
function count(to){const from=shown;shown=to;const t0=performance.now();(function f(n){const k=Math.min(1,(n-t0)/700);$('#pc').textContent=Math.round(from+(to-from)*k)+'% FORGIVEN';if(k<1)requestAnimationFrame(f)})(t0)}
$('#hb').addEventListener('click',()=>{if(pi>=CFG.steps.length)return;const p=CFG.steps[pi++];$('#pf').style.width=p+'%';$('#pb').setAttribute('aria-valuenow',p);count(p);$('#hb').textContent='🩷';
 const hb=$('#hb');hb.animate([{transform:'scale(1)'},{transform:'scale(1.35)'},{transform:'scale(1)'}],{duration:350});$('#fi').animate([{transform:'scale(1)'},{transform:'scale(1.12) rotate(-3deg)'},{transform:'scale(1)'}],{duration:450});
 const s=$('#s7');for(let i=0;i<5;i++){const h=document.createElement('i');h.textContent='💗';h.style.cssText=`position:absolute;left:${46+Math.random()*10}%;top:62%;font-size:18px;pointer-events:none;transition:transform 1.2s ease-out,opacity 1.2s`;s.append(h);requestAnimationFrame(()=>{h.style.transform=`translate(${(Math.random()-.5)*140}px,-${70+Math.random()*90}px)`;h.style.opacity=0});setTimeout(()=>h.remove(),1300)}
 if(p===100){setTimeout(()=>{$('#fi').src=CFG.imgs.hug;$('#fi').height=110},350);$('#pm').textContent="YOU'RE FORGIVEN! 💕";$('#hb').style.display='none';burst();setTimeout(()=>go(8),2600)}});
function burst(){const s=$('#s'+cur);for(let i=0;i<20;i++){const h=document.createElement('i');h.textContent=['💖','✨','🌸','💕'][i%4];h.style.cssText=`position:absolute;left:${Math.random()*90}%;top:100%;font-size:${16+Math.random()*14}px;transition:transform 2.6s ease-out,opacity 2.6s;pointer-events:none;z-index:5`;s.append(h);requestAnimationFrame(()=>{h.style.transform=`translateY(-${280+Math.random()*420}px)`;h.style.opacity=0});setTimeout(()=>h.remove(),2800)}}
// ----- restart -----
function reset(){pi=0;shown=0;done={};entry='';key('⌫');$('#pf').style.width='0';$('#pc').textContent='0% FORGIVEN';$('#fi').src=CFG.imgs.sleep;$('#fi').height=120;$('#pm').textContent='TAP THE HEART TO HEAL MY HEART.';$('#hb').style.display='';$('#hb').textContent='🤍';$('#qr').classList.remove('go');$('#tap').textContent='Tap the heart to scan'}
$('#qr').addEventListener('click',()=>{if($('#qr').classList.contains('go'))return;$('#qr').classList.add('go');$('#tap').textContent='Scanning… 💞';setTimeout(()=>go(0),1400)});
// ----- language / music / fullscreen -----
$('#lang').onchange=e=>$$('[data-t]').forEach(n=>{const v=I18N[e.target.value][n.dataset.t];if(v)n.textContent=v});
const a=$('#aud');$('#pp').onclick=()=>{if(a.paused)a.play().then(()=>{$('#pp').textContent='⏸'}).catch(()=>{$('#pp').title='Add assets/audio/music.mp3'});else{a.pause();$('#pp').textContent='▶'}};
$('#mu').onclick=()=>{a.muted=!a.muted;$('#mu').textContent=a.muted?'🔇':'🔊'};
$('#fs').onclick=()=>{try{document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen()}catch(e){}};
